// Browser stand-in for Node built-ins used by kordoc (generated by scripts/gen-node-shims.mjs).
// Functions kordoc only needs on a file system (CLI, OCR, native image tools) throw when called.
const fail=()=>{throw new Error("native module not available in browser")};
const P=new Proxy(fail,{get:(_t,k)=>k==="__esModule"?false:P,apply:fail});
export default P;
export const execFile=P;
export const execFileSync=P;
export const fork=P;
export const spawnSync=P;
